<template>
    <div>
        <div v-if="notice" class="ma-error ma-success" role="status">{{ notice }}</div>
        <div class="ma-panel"><div class="ma-panel-head"><div><h2>Bookings & Seats</h2><p class="ma-muted">Mobile bookings with separate booking and payment states. Dates filter when bookings were created.</p></div></div>
            <MobileFilters id="ma-bookings" v-model="filters" :options="options" search="Booking reference or passenger" dates environments terminals routes :statuses="['pending','confirmed','partially_cancelled','canceled','expired','review_required']" :busy="loading" @apply="load(1, true)" />
            <div v-if="error" class="ma-error m-3" role="alert">{{ error }} <button class="btn btn-outline-danger btn-sm ml-2" @click="load()">Retry</button></div>
            <div class="ma-table-wrap"><table class="ma-table"><thead><tr><th>Booking</th><th>Passenger</th><th>Journey</th><th>Seats</th><th>Booking state</th><th>Payment</th><th class="ma-numeric">Fare</th><th></th></tr></thead><tbody>
                <tr v-if="loading"><td colspan="8" class="ma-empty" role="status">Loading mobile bookings…</td></tr><template v-else><tr v-for="booking in items" :key="booking.id"><td><strong>{{ booking.invoice_id }}</strong><small>{{ time(booking.created_at) }}</small></td><td>{{ booking.passenger_name || '—' }}<small>{{ booking.passenger_mobile }}</small></td><td><strong>{{ booking.route_name || booking.departure || '—' }}</strong><small>{{ booking.travel_date }} · {{ booking.travel_time }}</small><small>{{ booking.terminal_name }}</small></td><td>{{ booking.seat_numbers?.join(', ') || '—' }}<small>{{ booking.active_seats }} active / {{ booking.seat_count }} total</small></td><td><span class="ma-badge" :class="booking.status">{{ label(booking.status) }}</span></td><td><span class="ma-badge" :class="booking.payment_status">{{ label(booking.payment_status) }}</span><small>{{ label(booking.payment_method) }}</small></td><td class="ma-numeric">{{ money(booking.total_fare) }}</td><td><button class="btn btn-outline-success btn-sm" @click="open(booking.invoice_id)">Details & seats</button></td></tr><tr v-if="!items.length && !error"><td colspan="8" class="ma-empty"><i class="fas fa-ticket-alt"></i>No mobile bookings match these filters.</td></tr></template>
            </tbody></table></div><MobilePagination :pagination="pagination" :busy="loading" @change="load" />
        </div>
        <MobileDialog v-if="selectedId" :title="`Booking ${selectedId}`" :busy="saving" @close="close">
            <p v-if="opening" class="ma-empty" role="status">Loading booking details…</p><div v-if="detailError" class="ma-error" role="alert">{{ detailError }} <button v-if="!detail" class="btn btn-outline-danger btn-sm ml-2" @click="open(selectedId)">Retry</button></div>
            <template v-if="detail">
                <dl class="ma-details"><div><dt>Passenger</dt><dd>{{ detail.passenger_name }} · {{ detail.passenger_mobile }}</dd></div><div><dt>Journey</dt><dd>{{ detail.route_name || detail.departure }}<br>{{ detail.travel_date }} · {{ detail.travel_time }}</dd></div><div><dt>Terminal</dt><dd>{{ detail.terminal_name || '—' }}</dd></div><div><dt>Booking status</dt><dd><span class="ma-badge" :class="detail.status">{{ label(detail.status) }}</span></dd></div><div><dt>Total fare</dt><dd>{{ money(detail.total_fare) }}</dd></div><div><dt>Recorded refund</dt><dd>{{ money(detail.refund_amount) }}</dd></div><div><dt>Payment</dt><dd>{{ label(detail.payment_status) }} · {{ label(detail.payment_method) }}</dd></div><div><dt>Created</dt><dd>{{ time(detail.created_at) }}</dd></div></dl>
                <h3>Ticket seats</h3><div class="ma-table-wrap mb-4"><table class="ma-table"><thead><tr><th>Seat</th><th>Ticket state</th><th class="ma-numeric">Fare</th></tr></thead><tbody><tr v-for="ticket in detail.tickets || []" :key="ticket.id"><td>{{ ticket.seat_no }}</td><td><span class="ma-badge" :class="ticket.deleted_at ? 'cancelled' : ticket.type">{{ ticket.type === 'reschedule' ? 'Rescheduled (history)' : ticket.deleted_at ? 'Removed' : ticket.type === 'booked' ? 'Confirmed' : ticket.type === 'advance booking' ? 'Reserved' : label(ticket.type) }}</span></td><td class="ma-numeric">{{ money(ticket.seat_fare) }}</td></tr></tbody></table></div>
                <form v-if="options.permissions.seats_remove && availableTickets.length" class="ma-form ma-panel ma-panel-body" @submit.prevent="removeSeats">
                    <div><h3>Remove booking seats</h3><p class="ma-muted">Selected seats are cancelled through ERP rules and released when permitted.</p></div>
                    <p class="ma-note ma-warning">A recorded financial refund does not send money through the payment gateway. Complete any gateway refund using the existing finance procedure.</p>
                    <p v-if="detail.seat_removal_policy?.message" class="ma-note ma-warning">{{ detail.seat_removal_policy.message }}</p>
                    <div class="ma-seat-grid"><label v-for="ticket in availableTickets" :key="ticket.id" class="ma-check ma-seat-choice"><input type="checkbox" :value="ticket.id" v-model="ticketIds" :disabled="saving || (isConfirmed(ticket) && !options.permissions.seats_refund)"><span>Seat {{ ticket.seat_no }}<small>{{ label(ticket.type) }}<span v-if="isConfirmed(ticket) && !options.permissions.seats_refund"> · Refund privilege required</span></small></span></label></div>
                    <div class="ma-grid"><div class="ma-field"><label for="ma-seat-reason">Removal reason</label><textarea id="ma-seat-reason" class="form-control" rows="2" v-model.trim="reason" minlength="3" maxlength="1000" required :disabled="saving" placeholder="Explain why these seats must be removed"></textarea></div><div class="ma-field"><label for="ma-refund">Refund percentage</label><input id="ma-refund" class="form-control" type="number" min="0" max="100" step="1" v-model.number="refund" :disabled="saving || !options.permissions.seats_refund || !selectedConfirmed || selectedReserved" required><p class="ma-muted">Calculated and validated by the ERP. Select confirmed seats separately to record a refund; reserved seats use 0%.</p></div></div>
                    <label class="ma-check"><input type="checkbox" v-model="confirmed" :disabled="saving"><span>I checked the booking and selected seats, and understand this action releases them.</span></label>
                    <div class="ma-actions"><button class="btn btn-danger" :disabled="saving || !ticketIds.length || reason.length < 3 || !confirmed || policyViolation">{{ saving ? 'Removing seats…' : `Remove ${ticketIds.length || ''} selected seat${ticketIds.length === 1 ? '' : 's'}` }}</button></div>
                </form>
                <p v-else-if="!options.permissions.seats_remove" class="ma-note">Your role can view this booking. Seat removal requires a separate privilege.</p>
            </template>
            <div class="ma-actions mt-4"><button type="button" class="btn btn-outline-secondary" :disabled="saving" @click="close">Close</button></div>
        </MobileDialog>
    </div>
</template>
<script>
import MobileFilters from './MobileFilters.vue'; import MobilePagination from './MobilePagination.vue'; import MobileDialog from './MobileDialog.vue';
import { request, today, label, money, displayTime } from './mobileApp';
export default {
    components: { MobileFilters, MobilePagination, MobileDialog }, props: { options: Object },
    data: () => ({ filters: { from: today(), to: today(), environment: 'live', search: '', status: '', terminal_id: '', route_id: '' }, applied: null, items: [], pagination: null, loading: false, error: '', notice: '', sequence: 0, openingSequence: 0, selectedId: null, detail: null, opening: false, detailError: '', saving: false, ticketIds: [], reason: '', refund: 0, confirmed: false }),
    computed: { availableTickets() { return (this.detail?.tickets || []).filter(ticket => !ticket.deleted_at && ['advance booking', 'booked'].includes(String(ticket.type).toLowerCase())); }, policyViolation() { const policy = this.detail?.seat_removal_policy || {}; return !!((policy.requires_full_cancellation && this.ticketIds.length !== this.availableTickets.length) || (policy.preserve_one_seat && this.ticketIds.length >= Number(this.detail?.active_seats || 0))); }, selectedConfirmed() { return this.availableTickets.some(ticket => this.ticketIds.includes(ticket.id) && this.isConfirmed(ticket)); }, selectedReserved() { return this.availableTickets.some(ticket => this.ticketIds.includes(ticket.id) && !this.isConfirmed(ticket)); } },
    watch: { ticketIds() { if (!this.selectedConfirmed || this.selectedReserved) this.refund = 0; } },
    mounted() { this.load(1, true); if (this.$route.query.booking) this.open(this.$route.query.booking); }, beforeUnmount() { this.sequence++; this.openingSequence++; },
    methods: {
        label, money, time: displayTime, isConfirmed(ticket) { return ['booked'].includes(String(ticket.type).toLowerCase()); },
        async load(page = 1, apply = false) { if (apply || !this.applied) this.applied = { ...this.filters }; const sequence = ++this.sequence; this.loading = true; this.error = ''; this.items = []; try { const data = await request(this, 'get', 'bookings', null, { ...this.applied, page }); if (sequence === this.sequence) { this.items = data.items; this.pagination = data.pagination; } } catch (error) { if (sequence === this.sequence) { this.error = error.message; this.pagination = null; } } finally { if (sequence === this.sequence) this.loading = false; } },
        async open(id) { const sequence = ++this.openingSequence; this.selectedId = id; this.detail = null; this.detailError = ''; this.ticketIds = []; this.reason = ''; this.refund = 0; this.confirmed = false; this.opening = true; try { const data = await request(this, 'get', `bookings/${encodeURIComponent(id)}`); if (sequence === this.openingSequence) this.detail = data; } catch (error) { if (sequence === this.openingSequence) this.detailError = error.message; } finally { if (sequence === this.openingSequence) this.opening = false; } },
        close() { if (this.saving) return; this.openingSequence++; this.selectedId = null; this.detail = null; if (this.$route.query.booking) this.$router.replace({ query: { ...this.$route.query, booking: undefined } }); },
        confirmLeave() { return !this.saving && (!this.ticketIds.length || window.confirm('Leave this booking without removing the selected seats?')); },
        async removeSeats() { if (this.saving || !this.ticketIds.length || !this.confirmed || this.reason.length < 3 || this.policyViolation) return; this.saving = true; this.detailError = ''; try { const result = await request(this, 'post', `bookings/${encodeURIComponent(this.selectedId)}/remove-seats`, { ticket_ids: this.ticketIds, reason: this.reason, refund_percentage: this.refund }); this.notice = result?.message || 'Selected seats removed. Any financial refund was recorded only; gateway refunds must be completed separately.'; await this.open(this.selectedId); await this.load(this.pagination?.current_page || 1); } catch (error) { this.detailError = error.message; } finally { this.saving = false; } },
    },
};
</script>
